"""Human-review proposals authored against the immutable Development v4 source.

K = retain, R = apply a wording-only draft revision, H = proposal held for Owner.
These are Codex assessments, never human acceptance or independent annotation.
"""


def K(reason, transformation="Original: giữ nguyên yêu cầu và projection đã đối chiếu với card/SQL."):
    return dict(action="KEEP", issue_type="NONE_IDENTIFIED", risk="LOW", reason=reason,
                proposed_wording=None, transformation=transformation)


def R(text, issue, reason, transformation):
    return dict(action="REVISE", issue_type=issue, risk="HIGH" if any(
        word in issue for word in ("PROJECTION", "FILTER", "COHORT", "BOUNDARY", "UNIT")) else "MEDIUM",
                reason=reason, proposed_wording=text, transformation=transformation)


def H(text, reason):
    return dict(action="HOLD", issue_type="TAXONOMY_LIMITATION", risk="MEDIUM", reason=reason,
                proposed_wording=text,
                transformation="Chưa xác lập được Reordering thứ hai khác biệt: cần Owner quyết định; không đổi nhãn/quota.")


